events = []
class Index:
    def __index__(self):
        events.append('length index')
        return 1
class Group:
    def __index__(self):
        events.append('group index')
        return 1
class Separator(str):
    def __len__(self):
        events.append('length')
        return Index()
    def __getitem__(self, index):
        raise AssertionError('getitem override')
    def __str__(self):
        raise AssertionError('str override')
    def __bytes__(self):
        raise AssertionError('bytes override')
sep = Separator('-')
group = Group()
assert b'ab'.hex(sep, group) == '61-62'
assert events == ['group index', 'length', 'length index']
events.clear()
error = ValueError('length failed')
class Failing(Separator):
    def __len__(self):
        events.append('length failure')
        raise error
sep = Failing('-')
try:
    b'ab'.hex(sep, group)
except ValueError as caught:
    assert caught is error
    assert caught.args == ('length failed',)
    assert caught.__context__ is None
else:
    assert False
assert events == ['group index', 'length failure']
events.clear()
class Huge(Group):
    def __index__(self):
        events.append('huge group')
        return 2**63
group = Huge()
try:
    b'ab'.hex(sep, group)
except OverflowError as caught:
    assert caught.args == ('Python int too large to convert to C int',)
else:
    assert False
assert events == ['huge group']

